class Solution { public int minFallingPathSum(int[][] matrix){int[] dp=matrix[0].clone();for(int row=1;row<matrix.length;row++){int[] next=new int[matrix.length];for(int col=0;col<matrix.length;col++){int best=dp[col];if(col>0)best=Math.min(best,dp[col-1]);if(col+1<matrix.length)best=Math.min(best,dp[col+1]);next[col]=matrix[row][col]+best;}dp=next;}return Arrays.stream(dp).min().getAsInt();} }
